import java.util.HashMap;
import java.util.Map;

class Solution {
    private Map<Integer, Integer> memo = new HashMap<>();

    public int minDays(int n) {
        memo.put(0, 0);
        memo.put(1, 1);
        return dfs(n);
    }

    private int dfs(int n) {
        if (memo.containsKey(n)) return memo.get(n);
        // Worst case: eat one orange per day
        int ans = n;
        // Option: make divisible by 2 by eating n%2 ones, then use the divide-by-2 operation (1 day), then solve for n/2
        ans = Math.min(ans, n % 2 + 1 + dfs(n / 2));
        // Option: make divisible by 3 by eating n%3 ones, then use the divide-by-3 operation (1 day), then solve for n/3
        ans = Math.min(ans, n % 3 + 1 + dfs(n / 3));
        memo.put(n, ans);
        return ans;
    }
}

